#!/usr/bin/env python3
"""
Proof-of-Concept: SSH SDCTR Rekeying Counter Race Condition

This script simulates the race condition described in RFC 4344 where
multiple threads increment the packet counter concurrently without
proper synchronization. This can lead to exceeding the 2^32 packet
limit before rekeying is triggered, causing keystream reuse or MAC
collisions.

The script uses a shared counter and multiple threads to demonstrate
the non-atomic increment and check operation.
"""

import threading
import time
import sys

# Constants from RFC 4344
MAX_PACKETS_BEFORE_REKEY = 2**32  # 4,294,967,296 packets
REKEY_CHECK_THRESHOLD = MAX_PACKETS_BEFORE_REKEY  # Threshold for rekeying

# Shared state
class SharedCounter:
    def __init__(self):
        self.packet_count = 0
        self.rekey_triggered = False
        self.lock = threading.Lock()  # Simulating proper synchronization (commented out to show race)

    def increment_and_check(self):
        """
        Simulates the non-atomic increment and check operation.
        In a vulnerable implementation, this would not be synchronized.
        """
        # Simulate a small delay to increase the chance of a race condition
        time.sleep(0.0001)
        
        # Read the current count
        current_count = self.packet_count
        
        # Check if rekeying is needed (non-atomic with increment)
        if current_count >= REKEY_CHECK_THRESHOLD:
            self.rekey_triggered = True
            print(f"[Thread {threading.current_thread().name}] Rekeying triggered at packet {current_count}")
            return
        
        # Increment the counter (non-atomic with check)
        self.packet_count = current_count + 1

    def increment_and_check_safe(self):
        """
        Simulates the atomic increment and check operation with proper synchronization.
        """
        with self.lock:
            current_count = self.packet_count
            
            if current_count >= REKEY_CHECK_THRESHOLD:
                self.rekey_triggered = True
                print(f"[Thread {threading.current_thread().name}] Rekeying triggered at packet {current_count}")
                return
            
            self.packet_count = current_count + 1

def worker(counter, num_packets, use_safe=False):
    """
    Worker function that simulates sending packets.
    """
    for _ in range(num_packets):
        if use_safe:
            counter.increment_and_check_safe()
        else:
            counter.increment_and_check()

def main():
    print("SSH SDCTR Rekeying Counter Race Condition PoC")
    print("=" * 50)
    
    # Simulate a high-throughput scenario with multiple threads
    num_threads = 10
    packets_per_thread = 10**6  # 1 million packets per thread
    
    print(f"Starting {num_threads} threads, each sending {packets_per_thread} packets...")
    print(f"Total packets: {num_threads * packets_per_thread}")
    print(f"Rekey threshold: {REKEY_CHECK_THRESHOLD}")
    print()
    
    # Test vulnerable implementation
    print("Testing VULNERABLE implementation (non-atomic increment/check):")
    vulnerable_counter = SharedCounter()
    threads = []
    
    start_time = time.time()
    for i in range(num_threads):
        t = threading.Thread(target=worker, args=(vulnerable_counter, packets_per_thread, False), name=f"Worker-{i}")
        threads.append(t)
        t.start()
    
    for t in threads:
        t.join()
    
    end_time = time.time()
    print(f"Vulnerable implementation completed in {end_time - start_time:.2f} seconds")
    print(f"Final packet count: {vulnerable_counter.packet_count}")
    print(f"Rekey triggered: {vulnerable_counter.rekey_triggered}")
    print()
    
    # Test safe implementation
    print("Testing SAFE implementation (atomic increment/check with lock):")
    safe_counter = SharedCounter()
    threads = []
    
    start_time = time.time()
    for i in range(num_threads):
        t = threading.Thread(target=worker, args=(safe_counter, packets_per_thread, True), name=f"Worker-{i}")
        threads.append(t)
        t.start()
    
    for t in threads:
        t.join()
    
    end_time = time.time()
    print(f"Safe implementation completed in {end_time - start_time:.2f} seconds")
    print(f"Final packet count: {safe_counter.packet_count}")
    print(f"Rekey triggered: {safe_counter.rekey_triggered}")
    print()
    
    # Analysis
    print("Analysis:")
    print("-" * 50)
    if vulnerable_counter.packet_count > REKEY_CHECK_THRESHOLD:
        print("VULNERABLE: Packet count exceeded rekey threshold without triggering rekey!")
        print("This demonstrates the race condition where multiple threads")
        print("read the counter before it is incremented, potentially exceeding")
        print("the 2^32 packet limit before the rekeying process is initiated.")
    else:
        print("SAFE: Packet count did not exceed rekey threshold.")
    
    if safe_counter.packet_count <= REKEY_CHECK_THRESHOLD:
        print("SAFE: Proper synchronization prevented the race condition.")
    else:
        print("UNEXPECTED: Safe implementation also exceeded threshold.")

if __name__ == "__main__":
    main()